function r(t){return`₱${t.toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}`}function e(t){return new Date(t).toLocaleDateString("en-PH",{month:"short",day:"numeric",year:"numeric"})}function i(t){return new Date(t).toLocaleString("en-PH",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}function o(t,n){return t==="percent"?`${n}%`:r(n)}export{e as a,i as b,o as c,r as f};
